// Generated by Cypress Author on 2026-11-26.
// Décrire le scénario d'affichage du contenu du panier Swag Labs.
describe('Swag Labs cart', () => {
    // Préparer une session utilisateur avant le scénario.
    beforeEach(() => {
        // Se connecter avec la commande partagée.
        cy.login();
        // Ajouter le Sauce Labs Backpack depuis inventory page
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible').click();
        // Vérifier que le badge indique un article avant d'ouvrir le panier.
        cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', 1);
    });

    // Fermer la session après le scénario.
    afterEach(() => {
        // Se déconnecter avec la commande partagée.
        cy.logout();
    });

    // Déclarer le scénario d'affichage du contenu du panier à compléter.
    it('affiche chaque article avec la quantité, le nom, la description et le prix attendus', () => {
        // Cliquer sur l'icone du panier
        cy.get('[data-test="shopping-cart-link"]').should('be.visible').click();
        // Vérifier que Le navigateur est dirigée vers La page du panier
        cy.location('pathname').should('eq', '/cart.html');
        // Vérifier que Le Titre de la page actuelle
        cy.get('[data-test="secondary-header"]').should('be.visible').and('have.text', 'Your Cart');

        // Vérifier que le panier contient l'article ajouté.
        cy.get('[data-test="item-quantity"]').should('have.text', '1');
        // Vérifier que le nom de l'article correspond au nom attendu.
        cy.get('[data-test="inventory-item-name"]').should('have.text', 'Sauce Labs Backpack');
        // Vérifier que la description de l'article correspond au description attendu.
        cy.get('[data-test="inventory-item-desc"]').should('have.text', 'carry.allTheThings() with the sleek, streamlined Sly Pack that melds uncompromising style with unequaled laptop and tablet protection.');
        // Vérifier que le prix de l'article correspond au prix attendu.
        cy.get('[data-test="inventory-item-price"]').should('have.text', '$29.99');
    });
});
